1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import Link from "next/link";
5	import { PENDING_PROMPT_KEY, PENDING_PROMPT_IMAGE_KEY } from "@/lib/pending-prompt";
6	import BuildingOverlay from "./BuildingOverlay";
7	import BuildRating from "./BuildRating";
8	
9	type Message = { role: string; content: string };
10	type BuildCheckpoint = { id: string; prompt: string; createdAt: string; filesWritten: number };
11	
12	type Props = {
13	  projectId: string;
14	  projectName: string;
15	  slug: string;
16	  published: boolean;
17	  initialFiles: Record<string, string>;
18	  initialMessages: Message[];
19	  initialBalance: number;
20	  /** This user's measured average credits per build — see lib/credits.ts. */
21	  avgBuildCredits: number;
22	};
23	
24	const SITES_BASE = process.env.NEXT_PUBLIC_SITES_BASE ?? "kodely.site";
25	
26	// Mirrors the publish route's own Host-based derivation (see the comment
27	// there) so the header's "live site" link always matches what publish
28	// actually returned, on staging or prod, without hardcoding either.
29	function liveSiteUrl(slug: string): string {
30	  if (typeof window === "undefined") return `https://${slug}.${SITES_BASE}`;
31	  const host = window.location.host;
32	  return host.includes("staging")
33	    ? `${window.location.origin}/api/site/${slug}`
34	    : `https://${slug}.${SITES_BASE}`;
35	}
36	
37	export default function Editor(props: Props) {
38	  const [messages, setMessages] = useState<Message[]>(props.initialMessages);
39	  const [files, setFiles] = useState(props.initialFiles);
40	  const [prompt, setPrompt] = useState("");
41	  const [busy, setBusy] = useState(false);
42	  const [status, setStatus] = useState<string | null>(null);
43	  const [error, setError] = useState<string | null>(null);
44	  const [balance, setBalance] = useState(props.initialBalance);
45	  // The build just finished in THIS session, so it can be rated. Deliberately
46	  // not restored on reload: rating a build you last saw yesterday is guesswork.
47	  const [lastBuildId, setLastBuildId] = useState<string | null>(null);
48	  const [previewNonce, setPreviewNonce] = useState(0);
49	  const [published, setPublished] = useState(props.published);
50	  const [publishing, setPublishing] = useState(false);
51	  const [view, setView] = useState<"preview" | "code" | "history">("preview");
52	  const [builds, setBuilds] = useState<BuildCheckpoint[] | null>(null);
53	  const [restoring, setRestoring] = useState<string | null>(null);
54	  const [activeFile, setActiveFile] = useState<string | null>(null);
55	  const [downloading, setDownloading] = useState(false);
56	  const [enhancing, setEnhancing] = useState(false);
57	  // The prompt as typed, held only while an expanded spec sits in the box.
58	  // Doubles as the "we're showing a spec" flag and as what Revert restores.
59	  const [enhancedFrom, setEnhancedFrom] = useState<string | null>(null);
60	  const streamingReply = useRef("");
61	
62	  async function openHistory() {
63	    setView("history");
64	    const res = await fetch(`/api/projects/${props.projectId}/builds`);
65	    const body = await res.json();
66	    setBuilds(body.builds ?? []);
67	  }
68	
69	  async function restore(buildId: string) {
70	    if (!confirm("Restore this checkpoint? Your current draft will be replaced.")) return;
71	    setRestoring(buildId);
72	    setError(null);
73	    try {
74	      const res = await fetch(`/api/projects/${props.projectId}/builds/${buildId}/restore`, {
75	        method: "POST",
76	      });
77	      const body = await res.json();
78	      if (!res.ok) throw new Error(body?.error ?? "Restore failed.");
79	      const res2 = await fetch(`/api/projects/${props.projectId}`);
80	      const body2 = await res2.json();
81	      const nextFiles: Record<string, string> = Object.fromEntries(
82	        (body2.project?.files ?? []).map((f: { path: string; content: string }) => [f.path, f.content]),
83	      );
84	      setFiles(nextFiles);
85	      setPreviewNonce((n) => n + 1);
86	      setView("preview");
87	    } catch (err) {
88	      setError(err instanceof Error ? err.message : "Restore failed.");
89	    } finally {
90	      setRestoring(null);
91	    }
92	  }
93	
94	  // The foundation means source files are never empty — "first build" means
95	  // no chat history yet, matching the same signal the generate route uses.
96	  const isFirstBuild = messages.length === 0;
97	
98	  // If the visitor typed a prompt on the homepage before hitting the auth
99	  // wall, that prompt survives login/signup in sessionStorage — fire it
100	  // automatically the moment they land in their new project, instead of
101	  // making them retype what they already told us.
102	  useEffect(() => {
103	    if (!isFirstBuild) return;
104	    let pending: string | null = null;
105	    let pendingImage: string | null = null;
106	    try {
107	      pending = sessionStorage.getItem(PENDING_PROMPT_KEY);
108	      pendingImage = sessionStorage.getItem(PENDING_PROMPT_IMAGE_KEY);
109	    } catch {}
110	    if (!pending) return;
111	    try {
112	      sessionStorage.removeItem(PENDING_PROMPT_KEY);
113	      sessionStorage.removeItem(PENDING_PROMPT_IMAGE_KEY);
114	    } catch {}
115	    send(pending, pendingImage ?? undefined);
116	    // Runs once on mount only — send() is intentionally not a dependency.
117	    // eslint-disable-next-line react-hooks/exhaustive-deps
118	  }, []);
119	
120	  async function send(overrideText?: string, image?: string) {
121	    const text = (overrideText ?? prompt).trim();
122	    if (!text || busy) return;
123	    if (balance <= 0) {
124	      setError("You're out of credits. Top up to keep building.");
125	      return;
126	    }
127	
128	    setBusy(true);
129	    setError(null);
130	    setStatus(isFirstBuild ? "Building your site…" : "Applying your changes…");
131	    setMessages((m) => [...m, { role: "user", content: text }]);
132	    setPrompt("");
133	    setEnhancedFrom(null);
134	    streamingReply.current = "";
135	
136	    try {
137	      const res = await fetch("/api/generate", {
138	        method: "POST",
139	        headers: { "Content-Type": "application/json" },
140	        body: JSON.stringify({ projectId: props.projectId, prompt: text, image }),
141	      });
142	
143	      if (!res.ok || !res.body) {
144	        const body = await res.json().catch(() => ({}));
145	        throw new Error(body?.error ?? "The build failed to start.");
146	      }
147	
148	      const reader = res.body.getReader();
149	      const decoder = new TextDecoder();
150	      let buffer = "";
151	      let touchedFiles = false;
152	
153	      while (true) {
154	        const { done, value } = await reader.read();
155	        if (done) break;
156	        buffer += decoder.decode(value, { stream: true });
157	
158	        const parts = buffer.split("\n\n");
159	        buffer = parts.pop() ?? "";
160	
161	        for (const part of parts) {
162	          if (!part.startsWith("data: ")) continue;
163	          const event = JSON.parse(part.slice(6));
164	
165	          if (event.type === "text") {
166	            streamingReply.current += event.text;
167	          } else if (event.type === "progress" || event.type === "status") {
168	            // Both drive the same line. `progress` comes from a real tool call,
169	            // `status` from a phase the route knows about (a repair pass).
170	            setStatus(event.text);
171	          } else if (event.type === "file") {
172	            // On the SDK engine these all arrive at once after the build, so
173	            // they are a completion signal, not live progress — the progress
174	            // line above is what the user actually watches.
175	            touchedFiles = true;
176	          } else if (event.type === "done") {
177	            setBalance(event.remaining);
178	            setStatus(null);
179	            setLastBuildId(event.buildId ?? null);
180	          } else if (event.type === "error") {
181	            throw new Error(event.message);
182	          }
183	        }
184	      }
185	
186	      if (streamingReply.current.trim()) {
187	        setMessages((m) => [...m, { role: "assistant", content: streamingReply.current.trim() }]);
188	      }
189	      if (touchedFiles) {
190	        const res2 = await fetch(`/api/projects/${props.projectId}`);
191	        const body = await res2.json();
192	        const nextFiles: Record<string, string> = Object.fromEntries(
193	          (body.project?.files ?? []).map((f: { path: string; content: string }) => [f.path, f.content]),
194	        );
195	        setFiles(nextFiles);
196	        setPreviewNonce((n) => n + 1);
197	      }
198	    } catch (err) {
199	      setError(err instanceof Error ? err.message : "Something went wrong.");
200	    } finally {
201	      setBusy(false);
202	      setStatus(null);
203	    }
204	  }
205	
206	  // Goes through fetch rather than a plain download link so a failure lands in
207	  // the same error strip as everything else here, instead of silently saving
208	  // the JSON error body as "slug.zip".
209	  async function downloadZip() {
210	    setDownloading(true);
211	    setError(null);
212	    try {
213	      const res = await fetch(`/api/projects/${props.projectId}/export`);
214	      if (!res.ok) {
215	        const body = await res.json().catch(() => ({}));
216	        throw new Error(body?.error ?? "Download failed.");
217	      }
218	      const url = URL.createObjectURL(await res.blob());
219	      const link = document.createElement("a");
220	      link.href = url;
221	      link.download = `${props.slug}.zip`;
222	      link.click();
223	      // The click hands the blob off asynchronously, so revoking in the same
224	      // tick can cancel the download in some browsers. Next tick is enough,
225	      // and skipping the revoke entirely would pin the archive in memory for
226	      // the life of the tab.
227	      setTimeout(() => URL.revokeObjectURL(url), 0);
228	    } catch (err) {
229	      setError(err instanceof Error ? err.message : "Download failed.");
230	    } finally {
231	      setDownloading(false);
232	    }
233	  }
234	
235	  // Expand the draft prompt into a spec the user can read and edit before
236	  // spending anything. The result lands in the prompt box itself — it is
237	  // already editable, and it is already what the build button reads — so
238	  // "accept" is just pressing Build, "edit" is typing, "discard" is Revert.
239	  async function enhance() {
240	    const text = prompt.trim();
241	    if (!text || enhancing || busy) return;
242	
243	    setEnhancing(true);
244	    setError(null);
245	    try {
246	      const res = await fetch("/api/enhance", {
247	        method: "POST",
248	        headers: { "Content-Type": "application/json" },
249	        // Always the ORIGINAL one-liner, never a spec we already produced —
250	        // re-expanding an expansion compounds invention instead of adding
251	        // detail.
252	        body: JSON.stringify({ prompt: enhancedFrom ?? text }),
253	      });
254	      const body = await res.json().catch(() => ({}));
255	      if (!res.ok || !body?.spec) throw new Error(body?.error ?? "Couldn't expand that.");
256	      setEnhancedFrom(enhancedFrom ?? text);
257	      setPrompt(body.spec);
258	    } catch (err) {
259	      // Nothing is lost: the typed prompt is still in the box and Build was
260	      // never disabled by this. Enhance is a convenience, never a gate.
261	      setError(err instanceof Error ? err.message : "Couldn't expand that.");
262	    } finally {
263	      setEnhancing(false);
264	    }
265	  }
266	
267	  function revert() {
268	    if (enhancedFrom === null) return;
269	    setPrompt(enhancedFrom);
270	    setEnhancedFrom(null);
271	  }
272	
273	  async function publish() {
274	    setPublishing(true);
275	    setError(null);
276	    try {
277	      const res = await fetch(`/api/projects/${props.projectId}/publish`, { method: "POST" });
278	      const body = await res.json();
279	      if (!res.ok) throw new Error(body?.error ?? "Publish failed.");
280	      setPublished(true);
281	      window.open(body.url, "_blank");
282	    } catch (err) {
283	      setError(err instanceof Error ? err.message : "Publish failed.");
284	    } finally {
285	      setPublishing(false);
286	    }
287	  }
288	
289	  return (
290	    <div className="flex h-screen flex-col">
291	      <header className="flex items-center justify-between border-b border-black/10 px-4 py-2.5 dark:border-white/10">
292	        <div className="flex items-center gap-3">
293	          <Link href="/dashboard" className="text-sm text-black/50 hover:text-black dark:text-white/50 dark:hover:text-white">
294	            ←
295	          </Link>
296	          <span className="text-sm font-medium">{props.projectName}</span>
297	        </div>
298	        <div className="flex items-center gap-3">
299	          <div className="flex items-center gap-1 rounded-lg border border-black/10 p-0.5 text-xs dark:border-white/10">
300	            <button
301	              onClick={() => setView("preview")}
302	              className={`rounded-md px-2 py-1 ${view === "preview" ? "bg-black text-white dark:bg-white dark:text-black" : "text-black/60 dark:text-white/60"}`}
303	            >
304	              Preview
305	            </button>
306	            <button
307	              onClick={() => {
308	                setView("code");
309	                setActiveFile((f) => f ?? Object.keys(files)[0] ?? null);
310	              }}
311	              className={`rounded-md px-2 py-1 ${view === "code" ? "bg-black text-white dark:bg-white dark:text-black" : "text-black/60 dark:text-white/60"}`}
312	              disabled={isFirstBuild}
313	            >
314	              Code
315	            </button>
316	            <button
317	              onClick={openHistory}
318	              className={`rounded-md px-2 py-1 ${view === "history" ? "bg-black text-white dark:bg-white dark:text-black" : "text-black/60 dark:text-white/60"}`}
319	              disabled={isFirstBuild}
320	            >
321	              History
322	            </button>
323	          </div>
324	          {/* Warn BEFORE the dead end, not at it. Fewer than two builds' worth
325	              left turns this amber and offers the top-up inline, so nobody
326	              discovers the problem halfway through a generation. */}
327	          {(() => {
328	            const buildsLeft = Math.floor(balance / props.avgBuildCredits);
329	            const low = balance > 0 && buildsLeft < 2;
330	            const out = balance <= 0;
331	            const cls = out
332	              ? "text-red-600 dark:text-red-400"
333	              : low
334	                ? "text-amber-600 dark:text-amber-500"
335	                : "text-black/50 dark:text-white/50";
336	            return (
337	              <span className={`text-xs ${cls}`}>
338	                {balance} credits
339	                {(low || out) && (
340	                  <>
341	                    {" · "}
342	                    <Link href="/pricing" className="underline underline-offset-2 hover:no-underline">
343	                      {out ? "top up" : buildsLeft < 1 ? "not enough for a build" : "running low"}
344	                    </Link>
345	                  </>
346	                )}
347	              </span>
348	            );
349	          })()}
350	          {published && (
351	            <a
352	              href={liveSiteUrl(props.slug)}
353	              target="_blank"
354	              className="text-xs text-black/50 underline hover:text-black dark:text-white/50 dark:hover:text-white"
355	            >
356	              live site ↗
357	            </a>
358	          )}
359	          <button
360	            onClick={publish}
361	            disabled={publishing || isFirstBuild}
362	            className="rounded-lg bg-black px-3 py-1.5 text-xs font-medium text-white disabled:opacity-40 dark:bg-white dark:text-black"
363	          >
364	            {publishing ? "Publishing…" : published ? "Republish" : "Publish"}
365	          </button>
366	        </div>
367	      </header>
368	
369	      <div className="flex min-h-0 flex-1">
370	        <div className="flex w-96 shrink-0 flex-col border-r border-black/10 dark:border-white/10">
371	          <div className="flex-1 space-y-3 overflow-y-auto p-4">
372	            {messages.length === 0 && (
373	              <p className="text-sm text-black/50 dark:text-white/50">
374	                Describe the site you want. Be specific — audience, purpose, tone.
375	              </p>
376	            )}
377	            {messages.map((m, i) => (
378	              <div key={i} className={m.role === "user" ? "text-sm" : "text-sm text-black/70 dark:text-white/70"}>
379	                <div className="mb-0.5 text-xs font-medium text-black/40 dark:text-white/40">
380	                  {m.role === "user" ? "You" : "Kodely"}
381	                </div>
382	                <div className="whitespace-pre-wrap">{m.content}</div>
383	              </div>
384	            ))}
385	            {status && (
386	              <div className="text-sm">
387	                <div className="mb-0.5 text-xs font-medium text-black/40 dark:text-white/40">
388	                  Kodely
389	                </div>
390	                <div className="flex items-center gap-2 text-black/60 dark:text-white/60">
391	                  {/* Three staggered dots. Under prefers-reduced-motion they
392	                      hold still rather than disappearing, so the line still
393	                      reads as "in progress" without the movement. */}
394	                  <span className="flex shrink-0 gap-1" aria-hidden="true">
395	                    {[0, 1, 2].map((i) => (
396	                      <span
397	                        key={i}
398	                        className="h-1 w-1 animate-[kodely-pulse_1.2s_ease-in-out_infinite] rounded-full bg-current opacity-40 motion-reduce:animate-none"
399	                        style={{ animationDelay: `${i * 0.16}s` }}
400	                      />
401	                    ))}
402	                  </span>
403	                  <span aria-live="polite">{status}</span>
404	                </div>
405	              </div>
406	            )}
407	            {/* Only once the build is done and its reply has landed — asking
408	                mid-stream would be asking about something half-written. */}
409	            {!busy && lastBuildId && (
410	              <BuildRating key={lastBuildId} buildId={lastBuildId} />
411	            )}
412	            {error && <div className="text-xs text-red-600">{error}</div>}
413	          </div>
414	          <div className="border-t border-black/10 p-3 dark:border-white/10">
415	            {enhancedFrom !== null && (
416	              <div className="mb-2 flex items-center justify-between gap-2 text-xs text-black/40 dark:text-white/40">
417	                <span>Expanded spec — edit before building</span>
418	                <button
419	                  onClick={revert}
420	                  className="underline underline-offset-2 hover:text-black dark:hover:text-white"
421	                >
422	                  Revert
423	                </button>
424	              </div>
425	            )}
426	            <textarea
427	              value={prompt}
428	              onChange={(e) => setPrompt(e.target.value)}
429	              onKeyDown={(e) => {
430	                // Enter sends a one-liner, but while a spec is on screen this
431	                // box is a multi-line editor — there, Enter has to make a
432	                // newline or the first paragraph break the user types starts a
433	                // build of a half-edited spec. The Build button still works.
434	                if (e.key === "Enter" && !e.shiftKey && enhancedFrom === null) {
435	                  e.preventDefault();
436	                  send();
437	                }
438	              }}
439	              placeholder={isFirstBuild ? "e.g. A landing page for a coffee roastery in Portland" : "Describe a change…"}
440	              // A ~200-word spec in a three-row box is unreviewable, and an
441	              // unreviewed spec defeats the point of showing one.
442	              rows={enhancedFrom !== null ? 12 : 3}
443	              className="w-full resize-none rounded-lg border border-black/15 bg-transparent px-3 py-2 text-sm outline-none focus:border-black/40 dark:border-white/15 dark:focus:border-white/40"
444	            />
445	            <div className="mt-2 flex gap-2">
446	              <button
447	                onClick={enhance}
448	                disabled={enhancing || busy || !prompt.trim()}
449	                title="Expand this into a fuller spec you can edit"
450	                className="shrink-0 rounded-lg border border-black/15 px-3 py-2 text-sm disabled:opacity-40 dark:border-white/15"
451	              >
452	                {enhancing ? "Enhancing…" : "Enhance"}
453	              </button>
454	              <button
455	                onClick={() => send()}
456	                disabled={busy || !prompt.trim()}
457	                className="flex-1 rounded-lg bg-black px-3 py-2 text-sm font-medium text-white disabled:opacity-40 dark:bg-white dark:text-black"
458	              >
459	                {busy ? "Building…" : isFirstBuild ? "Build site" : "Apply change"}
460	              </button>
461	            </div>
462	          </div>
463	        </div>
464	
465	        <div className="min-w-0 flex-1 bg-black/[0.02] dark:bg-white/[0.02]">
466	          {view === "preview" &&
467	            // While a build runs the iframe still shows the PREVIOUS version,
468	            // which reads as "nothing is happening". Covering it is the point:
469	            // the overlay is the only signal that work is underway.
470	            (busy ? (
471	              <BuildingOverlay status={status} />
472	            ) : (
473	              <iframe
474	                key={previewNonce}
475	                src={`/api/preview/${props.projectId}?v=${previewNonce}`}
476	                sandbox="allow-scripts allow-forms"
477	                className="h-full w-full border-0 bg-white"
478	                title="Live preview"
479	              />
480	            ))}
481	
482	          {view === "code" && (
483	            <div className="flex h-full">
484	              <div className="flex w-48 shrink-0 flex-col border-r border-black/10 dark:border-white/10">
485	                <div className="flex-1 overflow-y-auto p-2">
486	                  {Object.keys(files).map((path) => (
487	                    <button
488	                      key={path}
489	                      onClick={() => setActiveFile(path)}
490	                      className={`block w-full truncate rounded-md px-2 py-1.5 text-left text-xs ${
491	                        activeFile === path
492	                          ? "bg-black/10 font-medium dark:bg-white/10"
493	                          : "text-black/60 hover:bg-black/5 dark:text-white/60 dark:hover:bg-white/5"
494	                      }`}
495	                    >
496	                      {path}
497	                    </button>
498	                  ))}
499	                </div>
500	                <div className="border-t border-black/10 p-2 dark:border-white/10">
501	                  <button
502	                    onClick={downloadZip}
503	                    disabled={downloading}
504	                    className="w-full rounded-md border border-black/15 px-2 py-1 text-xs disabled:opacity-50 dark:border-white/15"
505	                  >
506	                    {downloading ? "Preparing…" : "Download .zip"}
507	                  </button>
508	                </div>
509	              </div>
510	              <div className="min-w-0 flex-1 overflow-auto">
511	                {activeFile && files[activeFile] !== undefined ? (
512	                  <div className="relative">
513	                    <button
514	                      onClick={() => navigator.clipboard.writeText(files[activeFile])}
515	                      className="absolute right-3 top-3 rounded-md border border-black/15 bg-white px-2 py-1 text-xs dark:border-white/15 dark:bg-black"
516	                    >
517	                      Copy
518	                    </button>
519	                    <pre className="p-4 text-xs leading-relaxed">
520	                      <code>{files[activeFile]}</code>
521	                    </pre>
522	                  </div>
523	                ) : (
524	                  <p className="p-4 text-sm text-black/50 dark:text-white/50">Select a file.</p>
525	                )}
526	              </div>
527	            </div>
528	          )}
529	
530	          {view === "history" && (
531	            <div className="h-full overflow-y-auto p-4">
532	              {builds === null ? (
533	                <p className="text-sm text-black/50 dark:text-white/50">Loading…</p>
534	              ) : builds.length === 0 ? (
535	                <p className="text-sm text-black/50 dark:text-white/50">No checkpoints yet.</p>
536	              ) : (
537	                <ul className="space-y-2">
538	                  {builds.map((b) => (
539	                    <li
540	                      key={b.id}
541	                      className="flex items-center justify-between rounded-lg border border-black/10 px-3 py-2 dark:border-white/10"
542	                    >
543	                      <div className="min-w-0">
544	                        <div className="truncate text-sm">{b.prompt}</div>
