5	// Thumbs up/down on the build that just finished.
6	//
7	// Kept deliberately small and easy to ignore. The moment someone has a working
8	// site is the moment they want to look at it, not fill in a survey — a modal
9	// here would buy a few more data points at the cost of the thing they came for.
10	//
11	// Thumbs-down opens a short reason list, because "it's bad" is not actionable
12	// and "the copy is generic" is. Thumbs-up submits immediately and stops: there
13	// is nothing to follow up on, and asking anyway reads as fishing.
14	
15	const REASONS: { id: string; label: string }[] = [
16	  { id: "looks-generic", label: "Looks generic" },
17	  { id: "wrong-content", label: "Wrong content" },
18	  { id: "layout-off", label: "Layout is off" },
19	  { id: "missing-something", label: "Missing something" },
20	  { id: "broken", label: "Something's broken" },
21	  { id: "other", label: "Other" },
22	];
23	
24	export default function BuildRating({ buildId }: { buildId: string }) {
25	  const [rating, setRating] = useState<"up" | "down" | null>(null);
26	  const [done, setDone] = useState(false);
27	
28	  async function send(value: "up" | "down", reason?: string) {
29	    setRating(value);
30	    if (value === "up" || reason) setDone(true);
31	
32	    // Fire and forget. A failed rating must never surface an error to someone
33	    // who was only trying to be helpful — it is our telemetry, not their task.
34	    try {
35	      await fetch("/api/feedback", {
36	        method: "POST",
37	        headers: { "Content-Type": "application/json" },
38	        body: JSON.stringify({ buildId, rating: value, reason }),
39	      });
40	    } catch {
41	      // ignored on purpose — see above
42	    }
43	  }
44	
45	  if (done) {
46	    return <p className="text-xs text-black/40 dark:text-white/40">Thanks — noted.</p>;
47	  }
48	
49	  if (rating === "down") {
50	    return (
51	      <div className="flex flex-col gap-1.5">
52	        <p className="text-xs text-black/40 dark:text-white/40">What was off?</p>
53	        <div className="flex flex-wrap gap-1.5">
54	          {REASONS.map((r) => (
55	            <button
56	              key={r.id}
57	              onClick={() => send("down", r.id)}
58	              className="rounded-full border border-black/10 px-2.5 py-1 text-xs text-black/60 hover:border-black/30 hover:text-black focus-visible:ring-2 focus-visible:ring-black/30 focus-visible:outline-none dark:border-white/10 dark:text-white/60 dark:hover:border-white/30 dark:hover:text-white"
59	            >
60	              {r.label}
61	            </button>
62	          ))}
63	        </div>
64	      </div>
65	    );
66	  }
67	
68	  return (
69	    <div className="flex items-center gap-2">
70	      <span className="text-xs text-black/40 dark:text-white/40">Was this what you wanted?</span>
71	      <button
72	        onClick={() => send("up")}
73	        aria-label="Yes, this is what I wanted"
74	        className="rounded-md px-1.5 py-0.5 text-sm text-black/40 hover:bg-black/5 hover:text-black focus-visible:ring-2 focus-visible:ring-black/30 focus-visible:outline-none dark:text-white/40 dark:hover:bg-white/5 dark:hover:text-white"
75	      >
76	        👍
77	      </button>
78	      <button
79	        onClick={() => send("down")}
80	        aria-label="No, this missed the mark"
81	        className="rounded-md px-1.5 py-0.5 text-sm text-black/40 hover:bg-black/5 hover:text-black focus-visible:ring-2 focus-visible:ring-black/30 focus-visible:outline-none dark:text-white/40 dark:hover:bg-white/5 dark:hover:text-white"
82	      >
83	        👎
84	      </button>
85	    </div>
86	  );
87	}
