/* ── Build-in-progress treatment (app/projects/[id]/BuildingOverlay.tsx) ──
   The Kodely mark breathes while a build runs. Scale only, and only 3% —
   enough to read as alive, small enough not to look like a loading spinner
   fighting for attention. */
@keyframes kodely-breathe {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.03);
  }
}
.kodely-breathe {
  animation: kodely-breathe 2.4s ease-in-out infinite;
}

/* Skeleton blocks: fade up into place once (staggered by inline delay), then
   a highlight sweeps across them continuously. `background-position` rather
   than a moving pseudo-element so there is nothing to clip or overflow. */
@keyframes kodely-skeleton-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes kodely-skeleton-sweep {
  from {
    background-position: 200% 0;
  }
  to {
    background-position: -200% 0;
  }
}
.kodely-skeleton {
  opacity: 0;
  background-color: color-mix(in oklab, currentColor 8%, transparent);
  background-image: linear-gradient(
    90deg,
    transparent 20%,
    color-mix(in oklab, currentColor 10%, transparent) 50%,
    transparent 80%
  );
  background-size: 200% 100%;
  animation:
    kodely-skeleton-in 0.45s ease-out forwards,
    kodely-skeleton-sweep 1.8s linear infinite;
}

/* Motion here is decoration, not information — the status line carries the
   meaning — so it is safe to drop entirely. The blocks must still be VISIBLE,
   hence opacity:1 rather than just cancelling the animation. */
@media (prefers-reduced-motion: reduce) {
  .kodely-breathe,
  .kodely-skeleton {
    animation: none;
  }
  .kodely-skeleton {
    opacity: 1;
  }
}

/* Staggered dots beside the live build-progress line in the editor chat.
   Opacity only — no transform — so the three dots never shift the text
