"use client";

// What the user sees when a build ends without finishing. Two causes, and they
// are NOT the same story, so they do not get the same message.
//
// Everything below was checked against app/api/generate/route.ts rather than
// assumed:
//
//  * The route's ReadableStream has a cancel() that calls abortController
//    .abort(). Aborting the client fetch triggers it.
//  * On that path `succeeded` stays false, so the Build row is written
//    status: FAILED, creditsCharged: 0, error "Client disconnected." The
//    ledger is never touched. Stopping is genuinely free.
//  * Files the agent already wrote were upserted by onWrite as it went, so
//    they ARE in the draft SOURCE tree. The compiled tree (kind: "build") is
//    only replaced inside the success branch, and /api/preview serves the
//    compiled tree — so the preview keeps showing the last version that
//    compiled. Both halves of that are true at once and the copy says so.
//  * The user's prompt was written to the messages table before streaming
//    started; the assistant's partial reply was not. So the prompt survives a
//    reload and the half-written reply does not.
//
// The connection-loss case is deliberately vaguer, because the truth is
// vaguer. A dropped TCP connection does not always reach the server as a
// cancel — if it does, the build is abandoned and costs nothing; if it does
// not (half-open socket, laptop asleep), the build runs to completion on the
// server, saves its files and charges for them. From the browser these two
// are indistinguishable. There is no resume, no reattach and no polling
// endpoint for an in-flight build, so the only honest instruction is
// "reload and look".

export type Interruption = "stopped" | "connection-lost";

const FOCUS_RING =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40";

export default function BuildInterrupted({
  kind,
  onDismiss,
}: {
  kind: Interruption;
  onDismiss: () => void;
}) {
  const stopped = kind === "stopped";

  return (
    <div
      role="status"
      aria-live="polite"
      className="rounded-lg border border-black/10 p-3 dark:border-white/10"
    >
      <p className="text-sm font-medium">
        {stopped ? "Build stopped" : "Lost connection to the build"}
      </p>

      {stopped ? (
        <ul className="mt-1.5 space-y-1 text-xs text-black/60 dark:text-white/60">
          <li>You weren&rsquo;t charged. A stopped build costs 0 credits.</li>
          <li>
            Your preview and published site are untouched — they still show the last version
            that finished compiling.
          </li>
          <li>
            Any files the build had already written are kept in Code, so a stopped build can
            leave the source part-way through a change.
          </li>
        </ul>
      ) : (
        <ul className="mt-1.5 space-y-1 text-xs text-black/60 dark:text-white/60">
          <li>
            The build was still running when the stream to your browser ended. There is no way
            to reattach to it from here.
          </li>
          <li>
            It either stopped on the server — in which case it cost you nothing — or ran to the
            end and saved. We can&rsquo;t tell which from this tab.
          </li>
          <li>Reload to see where your project and credit balance actually stand.</li>
        </ul>
      )}

      <div className="mt-2.5 flex gap-2">
        <button
          type="button"
          onClick={() => window.location.reload()}
          className={`rounded-md border border-black/15 px-2 py-1 text-xs dark:border-white/15 ${FOCUS_RING}`}
        >
          Reload
        </button>
        <button
          type="button"
          onClick={onDismiss}
          className={`rounded-md px-2 py-1 text-xs text-black/50 hover:text-black dark:text-white/50 dark:hover:text-white ${FOCUS_RING}`}
        >
          Dismiss
        </button>
      </div>
    </div>
  );
}

